/* ---------------------------------------------------------------------------
 * 常量
 * ------------------------------------------------------------------------- */

const GAME_ID = 'quiz-party';

/** 每题限时（毫秒）。 */
const LIMIT_MS = 15000;

/** 答对的基础分。 */
const BASE_POINTS = 100;

/** 速度分上限（剩余时间越满给越多）。 */
const SPEED_MAX = 60;

/** 连对加成：每连对一次 +10，连对 5 次封顶（+50）。 */
const STREAK_STEP = 10;
const STREAK_CAP = 5;

/** 双人 P2P 局的「抢先答对」额外加分。 */
const FIRST_BONUS = 30;

/** 每题的选项个数。 */
const OPTION_COUNT = 4;

/** 一局默认题数。 */
const DEFAULT_TOTAL = 10;

/* ---------------------------------------------------------------------------
 * 哈希与伪随机
 * ------------------------------------------------------------------------- */

/** FNV-1a 32 位哈希。 */
function fnv1a(str) {
  const s = String(str);
  let h = 0x811c9dc5;
  for (let i = 0; i < s.length; i++) {
    h ^= s.charCodeAt(i);
    h = (h + ((h << 1) + (h << 4) + (h << 7) + (h << 8) + (h << 24))) >>> 0;
  }
  return h >>> 0;
}

/**
 * mulberry32 —— 纯 JS 伪随机。
 * 返回一个带计数的取数器：count 就是「随机数序号」，
 * 必须进 hashState，否则房主能偷偷换题序。
 */
