    rngCounter: layout.rngCounter,
    round: 0,
    phase: 'question',        /* question → review → question … → done */
    picks: [],                /* [{r, p, c, ms}]，按提交先后排列 */
    timeouts: [],             /* [{r, p}] 超时没答的人 */
    closed: [],               /* [r] 已结算（close）的题 */
